import { Suspense, lazy } from "react";
import { Routes, Route, Navigate } from "react-router-dom";
import { useAuth } from "@/contexts/auth-context";
import { AppShell } from "./components/layout/app-shell";
import { useRTL } from "./hooks/useRTL";
import LoginPage from "./pages/login";
import type { ReactNode } from "react";

// Lazy-loaded pages (BATCH-48)
const DashboardPage = lazy(() => import("./pages/dashboard"));
const PipelineNewPage = lazy(() => import("./pages/pipeline-new"));
const RunDetailPage = lazy(() => import("./pages/run-detail"));
const IdeasBrowserPage = lazy(() => import("./pages/ideas-browser"));
const IdeaDetailPage = lazy(() => import("./pages/idea-detail"));
const GapsExplorerPage = lazy(() => import("./pages/gaps-explorer"));
const GapDetailPage = lazy(() => import("./pages/gap-detail"));
const KnowledgeSearchPage = lazy(() => import("./pages/knowledge-search"));
const SettingsPage = lazy(() => import("./pages/settings"));
const LiteraturePage = lazy(() => import("./pages/literature"));
const MemoryBrowserPage = lazy(() => import("./pages/memory"));
const CostsPage = lazy(() => import("./pages/costs"));
const GovernancePage = lazy(() => import("./pages/governance"));
const TracesPage = lazy(() => import("./pages/traces"));
const SessionsPage = lazy(() => import("./pages/sessions"));
const KnowledgeGraphPage = lazy(() => import("./pages/knowledge-graph"));
const AutonomousPage = lazy(() => import("./pages/autonomous"));
const PluginsPage = lazy(() => import("./pages/plugins"));

function LoadingScreen() {
  return (
    <div className="flex items-center justify-center h-screen">
      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
    </div>
  );
}

/** Redirects to /login if not authenticated (BATCH-28). */
function ProtectedRoute({ children }: { children: ReactNode }) {
  const { user, loading } = useAuth();
  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <span className="text-muted-foreground">Loading...</span>
      </div>
    );
  }
  if (!user) {
    return <Navigate to="/login" replace />;
  }
  return <>{children}</>;
}

export default function App() {
  useRTL();
  return (
    <Routes>
      <Route path="/login" element={<LoginPage />} />
      <Route
        path="/*"
        element={
          <ProtectedRoute>
            <AppShell>
              <Suspense fallback={<LoadingScreen />}>
                <Routes>
                  <Route path="/" element={<DashboardPage />} />
                  <Route path="/pipeline/new" element={<PipelineNewPage />} />
                  <Route path="/runs/:id" element={<RunDetailPage />} />
                  <Route path="/ideas" element={<IdeasBrowserPage />} />
                  <Route path="/ideas/:id" element={<IdeaDetailPage />} />
                  <Route path="/gaps" element={<GapsExplorerPage />} />
                  <Route path="/gaps/:id" element={<GapDetailPage />} />
                  <Route path="/knowledge" element={<KnowledgeSearchPage />} />
                  <Route path="/settings" element={<SettingsPage />} />
                  <Route path="/costs" element={<CostsPage />} />
                  <Route path="/memory" element={<MemoryBrowserPage />} />
                  <Route path="/governance" element={<GovernancePage />} />
                  <Route path="/traces" element={<TracesPage />} />
                  <Route path="/sessions" element={<SessionsPage />} />
                  <Route path="/literature" element={<LiteraturePage />} />
                  <Route path="/knowledge-graph" element={<KnowledgeGraphPage />} />
                  <Route path="/autonomous" element={<AutonomousPage />} />
                  <Route path="/plugins" element={<PluginsPage />} />
                  <Route path="*" element={<Navigate to="/" replace />} />
                </Routes>
              </Suspense>
            </AppShell>
          </ProtectedRoute>
        }
      />
    </Routes>
  );
}

import { NavLink } from "react-router-dom";
import {
  LayoutDashboard,
  Play,
  Lightbulb,
  GitBranch,
  Search,
  Settings,
  DollarSign,
  Brain,
  Shield,
  Activity,
  Layers,
  BookMarked,
  BrainCircuit,
  Cpu,
  Puzzle,
} from "lucide-react";
import { cn } from "@/lib/utils";

interface NavItem {
  to: string;
  icon: React.ElementType;
  label: string;
  /** Show in mobile bottom nav (limited space) */
  mobile?: boolean;
}

const NAV_ITEMS: NavItem[] = [
  { to: "/", icon: LayoutDashboard, label: "Dashboard", mobile: true },
  { to: "/pipeline/new", icon: Play, label: "Pipeline", mobile: true },
  { to: "/ideas", icon: Lightbulb, label: "Ideas", mobile: true },
  { to: "/gaps", icon: GitBranch, label: "Gaps" },
  { to: "/knowledge", icon: Search, label: "Knowledge" },
  { to: "/settings", icon: Settings, label: "Settings" },
  { to: "/costs", icon: DollarSign, label: "Costs" },
  { to: "/memory", icon: Brain, label: "Memory" },
  { to: "/governance", icon: Shield, label: "Governance" },
  { to: "/traces", icon: Activity, label: "Traces" },
  { to: "/sessions", icon: Layers, label: "Sessions" },
  { to: "/literature", icon: BookMarked, label: "Literature" },
  { to: "/knowledge-graph", icon: BrainCircuit, label: "Graph" },
  { to: "/autonomous", icon: Cpu, label: "Autonomous", mobile: true },
  { to: "/plugins", icon: Puzzle, label: "Plugins" },
];

export function Sidebar({ collapsed }: { collapsed: boolean }) {
  return (
    <nav className="p-2 space-y-1">
      {NAV_ITEMS.map((item) => (
        <NavLink
          key={item.to}
          to={item.to}
          end={item.to === "/"}
          className={({ isActive }) =>
            cn(
              "flex items-center gap-3 rounded-md px-3 py-2 text-sm transition-colors",
              isActive
                ? "bg-primary/10 text-primary font-medium"
                : "text-muted-foreground hover:bg-accent hover:text-accent-foreground",
            )
          }
        >
          <item.icon className="h-4 w-4 flex-shrink-0" />
          {!collapsed && <span className="truncate">{item.label}</span>}
        </NavLink>
      ))}
    </nav>
  );
}

/** Mobile bottom navigation — renders on small screens only. */
export function MobileBottomNav() {
  const mobileItems = NAV_ITEMS.filter((item) => item.mobile);

  return (
    <nav className="app-bottom-nav" aria-label="Mobile navigation">
      {mobileItems.map((item) => (
        <NavLink
          key={item.to}
          to={item.to}
          end={item.to === "/"}
          className={({ isActive }) =>
            cn(
              "flex flex-col items-center gap-0.5 text-[0.625rem] px-1 py-1 rounded-md transition-colors",
              isActive
                ? "text-primary"
                : "text-muted-foreground hover:text-primary",
            )
          }
        >
          <item.icon className="h-5 w-5" />
          <span>{item.label}</span>
        </NavLink>
      ))}
    </nav>
  );
}

import { useQuery } from "@tanstack/react-query";
import { lazy, Suspense } from "react";
import { listRuns } from "@/api/pipeline";
import { getSystemStatus } from "@/api/status";
import { listIdeas } from "@/api/ideas";
import { RunCard } from "@/components/pipeline/run-card";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { useNavigate } from "react-router-dom";
import { Activity, Lightbulb, FlaskConical, Server } from "lucide-react";

const ScoreDistributionChart = lazy(() =>
  import("@/components/charts/score-distribution").then((m) => ({ default: m.ScoreDistributionChart })),
);
const DomainBreakdownChart = lazy(() =>
  import("@/components/charts/domain-breakdown").then((m) => ({ default: m.DomainBreakdownChart })),
);
const RunStatusChart = lazy(() =>
  import("@/components/charts/run-status-chart").then((m) => ({ default: m.RunStatusChart })),
);

export default function Dashboard() {
  const navigate = useNavigate();

  const { data: status, isLoading: statusLoading } = useQuery({
    queryKey: ["status"],
    queryFn: getSystemStatus,
  });

  const { data: runsData, isLoading: runsLoading } = useQuery({
    queryKey: ["runs", { limit: 5 }],
    queryFn: () => listRuns({ limit: 5 }),
  });

  const { data: ideasData, isLoading: ideasLoading } = useQuery({
    queryKey: ["ideas", { limit: 5 }],
    queryFn: () => listIdeas({ limit: 5 }),
  });

  const { data: chartIdeas } = useQuery({
    queryKey: ["ideas", { limit: 200 }],
    queryFn: () => listIdeas({ limit: 200 }),
  });

  const { data: chartRuns } = useQuery({
    queryKey: ["runs", { limit: 50 }],
    queryFn: () => listRuns({ limit: 50 }),
  });

  const hasChartData =
    (chartIdeas?.ideas.length ?? 0) > 0 || (chartRuns?.runs.length ?? 0) > 0;

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Dashboard</h1>
        <p className="text-muted-foreground">Overview of your research pipeline.</p>
      </div>

      <div className="dashboard-grid grid gap-4 md:grid-cols-3">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">Total Runs</CardTitle>
            <Activity className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            {runsLoading ? (
              <Skeleton className="h-8 w-16" />
            ) : (
              <span className="text-2xl font-bold">{runsData?.total ?? 0}</span>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">Total Ideas</CardTitle>
            <Lightbulb className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            {ideasLoading ? (
              <Skeleton className="h-8 w-16" />
            ) : (
              <span className="text-2xl font-bold">{ideasData?.total ?? 0}</span>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium">System</CardTitle>
            <Server className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            {statusLoading ? (
              <Skeleton className="h-8 w-24" />
            ) : (
              <div>
                <span className="text-2xl font-bold">{status?.app_name ?? "—"}</span>
                <p className="text-xs text-muted-foreground">v{status?.version ?? "—"}</p>
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {hasChartData && (
        <Suspense fallback={<Skeleton className="h-64 w-full" />}>
          <div className="space-y-4">
            <h2 className="text-lg font-semibold">Analytics</h2>
            <div className="grid gap-4 md:grid-cols-2">
              <Card>
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Score Distribution</CardTitle>
                </CardHeader>
                <CardContent>
                  <ScoreDistributionChart ideas={chartIdeas?.ideas ?? []} />
                </CardContent>
              </Card>
              <Card>
                <CardHeader>
                  <CardTitle className="text-sm font-medium">Run Status</CardTitle>
                </CardHeader>
                <CardContent>
                  <RunStatusChart runs={chartRuns?.runs ?? []} />
                </CardContent>
              </Card>
            </div>
            <Card>
              <CardHeader>
                <CardTitle className="text-sm font-medium">Ideas by Domain</CardTitle>
              </CardHeader>
              <CardContent>
                <DomainBreakdownChart ideas={chartIdeas?.ideas ?? []} />
              </CardContent>
            </Card>
          </div>
        </Suspense>
      )}

      <div className="grid gap-6 md:grid-cols-2">
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-semibold">Recent Runs</h2>
            <button
              onClick={() => navigate("/pipeline/new")}
              className="text-sm text-primary hover:underline"
            >
              New run
            </button>
          </div>
          {runsLoading ? (
            <div className="space-y-2">
              {Array.from({ length: 3 }).map((_, i) => (
                <Skeleton key={i} className="h-16 w-full" />
              ))}
            </div>
          ) : runsData?.runs.length ? (
            runsData.runs.map((run) => (
                <RunCard key={run.id} run={run} onClick={() => navigate(`/runs/${run.id}`)} />
              ))
          ) : (
            <Card>
              <CardContent className="p-8 text-center text-muted-foreground">
                <FlaskConical className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No runs yet. Start your first pipeline!</p>
              </CardContent>
            </Card>
          )}
        </div>

        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <h2 className="text-lg font-semibold">Recent Ideas</h2>
            <button
              onClick={() => navigate("/ideas")}
              className="text-sm text-primary hover:underline"
            >
              View all
            </button>
          </div>
          {ideasLoading ? (
            <div className="space-y-2">
              {Array.from({ length: 3 }).map((_, i) => (
                <Skeleton key={i} className="h-16 w-full" />
              ))}
            </div>
          ) : ideasData?.ideas.length ? (
            ideasData.ideas.map((idea) => (
              <Card
                key={idea.id}
                className="cursor-pointer hover:bg-accent/50 transition-colors"
                onClick={() => navigate(`/ideas/${idea.id}`)}
              >
                <CardContent className="p-4">
                  <p className="text-sm font-medium line-clamp-1">{idea.title}</p>
                  <p className="text-xs text-muted-foreground">{idea.domain}</p>
                </CardContent>
              </Card>
            ))
          ) : (
            <Card>
              <CardContent className="p-8 text-center text-muted-foreground">
                <Lightbulb className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No ideas generated yet.</p>
              </CardContent>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { RunConfigForm } from "@/components/pipeline/run-config-form";
import { AutonomousForm } from "@/components/pipeline/autonomous-form";
import { StageProgress } from "@/components/pipeline/stage-progress";
import { usePipelineProgress } from "@/hooks/usePipelineProgress";
import { triggerRun, getRunIdeas, cancelRun } from "@/api/pipeline";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import type { PipelineRunRequest, IdeaSummary } from "@/api/types";
import { CheckCircle2, Lightbulb, AlertCircle, XCircle } from "lucide-react";

export default function PipelineNew() {
  const navigate = useNavigate();
  const [runId, setRunId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [ideas, setIdeas] = useState<IdeaSummary[]>([]);
  const [ideasError, setIdeasError] = useState<string | null>(null);
  const [ideasLoading, setIdeasLoading] = useState(false);
  const [sessionId, setSessionId] = useState<string>("");
  const { stages, isComplete, isConnected } = usePipelineProgress(runId);

  // ── Cancel run state ──────────────────────────────────────────
  const [isCancelling, setIsCancelling] = useState(false);
  const [isCancelled, setIsCancelled] = useState(false);
  const [showCancelConfirm, setShowCancelConfirm] = useState(false);
  const [cancelError, setCancelError] = useState<string | null>(null);

  const isRunning = !!runId && !isComplete && isConnected && !isCancelled;
  const completedStages = stages.filter((s) => s.status === "completed");
  const hasPartialResults = isCancelled && completedStages.length > 0;

  async function handleStart(config: PipelineRunRequest) {
    setIsLoading(true);
    setError(null);
    setIdeas([]);
    setIdeasError(null);
    try {
      const configWithSession = {
        ...config,
        session_id: sessionId || undefined,
      };
      const res = await triggerRun(configWithSession);
      setRunId(res.run_id);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to start pipeline");
    } finally {
      setIsLoading(false);
    }
  }

  // Fetch ideas when pipeline completes
  useEffect(() => {
    if (!isComplete) return;

    async function fetchIdeas() {
      setIdeasLoading(true);
      setIdeasError(null);
      try {
        const { listRuns } = await import("@/api/pipeline");
        const runsData = await listRuns({ limit: 1 });
        if (runsData.runs.length > 0) {
          const latestRun = runsData.runs[0];
          const ideasData = await getRunIdeas(latestRun.id);
          setIdeas(ideasData.ideas);
        }
      } catch (err) {
        setIdeasError(err instanceof Error ? err.message : "Failed to load results");
      } finally {
        setIdeasLoading(false);
      }
    }

    fetchIdeas();
  }, [isComplete]);

  // ── Cancel handlers (AR-01: explicit user confirmation) ───────
  function handleCancelClick() {
    setCancelError(null);
    setShowCancelConfirm(true);
  }

  function handleCancelDismiss() {
    setShowCancelConfirm(false);
  }

  async function handleCancelConfirm() {
    if (!runId) return;
    setIsCancelling(true);
    setCancelError(null);
    try {
      await cancelRun(runId);
      setIsCancelled(true);
      setShowCancelConfirm(false);
    } catch (err) {
      setCancelError(err instanceof Error ? err.message : "Failed to cancel run");
    } finally {
      setIsCancelling(false);
    }
  }

  function handleReset() {
    setRunId(null);
    setIdeas([]);
    setIdeasError(null);
    setError(null);
    setIsCancelled(false);
    setCancelError(null);
    setShowCancelConfirm(false);
  }

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Pipeline</h1>
        <p className="text-muted-foreground">Configure and launch a research pipeline.</p>
      </div>

      {!runId && (
        <>
          <Card>
            <CardContent className="p-4">
              <div className="space-y-2">
                <label className="text-sm font-medium" htmlFor="session-id-input">
                  Session ID (optional)
                </label>
                <input
                  id="session-id-input"
                  type="text"
                  placeholder="e.g., my-session-name"
                  value={sessionId}
                  onChange={(e) => setSessionId(e.target.value)}
                  data-testid="session-id-input"
                  className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                  maxLength={200}
                />
                <p className="text-xs text-muted-foreground">
                  Group multiple runs under the same session for easy tracking.
                </p>
              </div>
            </CardContent>
          </Card>
          <Tabs defaultValue="single">
            <TabsList>
              <TabsTrigger value="single">Single Run</TabsTrigger>
              <TabsTrigger value="autonomous">Autonomous Cycle</TabsTrigger>
            </TabsList>
            <TabsContent value="single">
              <RunConfigForm onSubmit={handleStart} isLoading={isLoading} />
            </TabsContent>
            <TabsContent value="autonomous">
              <AutonomousForm onCycleStarted={setRunId} />
            </TabsContent>
          </Tabs>
        </>
      )}

      {error && (
        <Card className="border-destructive">
          <CardContent className="p-4 text-sm text-destructive">{error}</CardContent>
        </Card>
      )}

      {runId && (
        <Card>
          <CardHeader>
            <div className="flex items-center justify-between">
              <CardTitle className="text-lg">Pipeline Progress</CardTitle>
              <div className="flex items-center gap-2">
                <Badge variant="outline">Run #{runId}</Badge>
                {isCancelled ? (
                  <Badge className="bg-red-100 text-red-800" data-testid="cancelled-badge">
                    Cancelled
                  </Badge>
                ) : isComplete ? (
                  <Badge className="bg-green-100 text-green-800">Complete</Badge>
                ) : isConnected ? (
                  <Badge className="bg-blue-100 text-blue-800">Live</Badge>
                ) : (
                  <Badge variant="secondary">Connecting...</Badge>
                )}
                {isRunning && (
                  <Button
                    variant="destructive"
                    size="sm"
                    onClick={handleCancelClick}
                    disabled={isCancelling}
                    data-testid="cancel-run-btn"
                  >
                    {isCancelling ? "Cancelling…" : "Cancel Run"}
                  </Button>
                )}
              </div>
            </div>
          </CardHeader>
          <CardContent>
            <StageProgress stages={stages} currentStage={null} />
          </CardContent>

          {/* Cancel confirmation dialog (AR-01) */}
          {showCancelConfirm && (
            <div
              className="fixed inset-0 z-50 flex items-center justify-center bg-black/50"
              data-testid="cancel-confirm-dialog"
            >
              <Card className="w-full max-w-md mx-4">
                <CardHeader>
                  <div className="flex items-center gap-2">
                    <AlertCircle className="h-5 w-5 text-destructive" />
                    <CardTitle className="text-lg">Cancel Pipeline Run?</CardTitle>
                  </div>
                </CardHeader>
                <CardContent className="space-y-4">
                  <p className="text-sm text-muted-foreground">
                    This will abort the running pipeline. Any stages that have already
                    completed will be preserved, but no further stages will execute.
                  </p>
                  {cancelError && (
                    <p className="text-sm text-destructive" data-testid="cancel-error">
                      {cancelError}
                    </p>
                  )}
                  <div className="flex justify-end gap-2">
                    <Button
                      variant="outline"
                      onClick={handleCancelDismiss}
                      data-testid="cancel-dismiss-btn"
                    >
                      No, Continue
                    </Button>
                    <Button
                      variant="destructive"
                      onClick={handleCancelConfirm}
                      disabled={isCancelling}
                      data-testid="cancel-confirm-btn"
                    >
                      {isCancelling ? "Cancelling…" : "Yes, Cancel Run"}
                    </Button>
                  </div>
                </CardContent>
              </Card>
            </div>
          )}

          {isComplete && (
            <CardContent className="border-t pt-4">
              <div className="flex items-center gap-2 text-green-700">
                <CheckCircle2 className="h-5 w-5" />
                <span className="font-medium">Pipeline completed successfully</span>
              </div>
            </CardContent>
          )}

          {isCancelled && (
            <CardContent className="border-t pt-4" data-testid="cancelled-partial-results">
              <div className="flex items-center gap-2 text-red-700">
                <XCircle className="h-5 w-5" />
                <span className="font-medium">Pipeline run was cancelled</span>
              </div>
              {hasPartialResults && (
                <p className="text-sm text-muted-foreground mt-1">
                  {completedStages.length} of {stages.length} stage{completedStages.length !== 1 ? "s" : ""} completed before cancellation.
                </p>
              )}
            </CardContent>
          )}
        </Card>
      )}

      {(isComplete || isCancelled) && (
        <div className="space-y-4" data-testid="pipeline-results">
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  {isComplete ? (
                    <>
                      <CheckCircle2 className="h-5 w-5 text-green-600" />
                      <CardTitle className="text-lg">Pipeline Complete</CardTitle>
                    </>
                  ) : (
                    <>
                      <XCircle className="h-5 w-5 text-red-600" />
                      <CardTitle className="text-lg">Pipeline Cancelled</CardTitle>
                    </>
                  )}
                </div>
                <div className="flex items-center gap-3 text-sm text-muted-foreground">
                  {ideas.length > 0 && (
                    <span className="flex items-center gap-1">
                      <Lightbulb className="h-4 w-4" />
                      {ideas.length} idea{ideas.length !== 1 ? "s" : ""} generated
                    </span>
                  )}
                </div>
              </div>
